/**
 * 把 `src/` 打成 DSH 的浏览器插件产物 `lib/client.js`。
 *
 * DSH 的 client 半不是普通 ESM：它由 `window.__ModuleLoader__.load({id, factory})`
 * 装载，`factory(require)` 里的 `require` 由运行时解析共享依赖。
 * 官方产物长这样（已比对 dsh-client-ui-account-notifications）：
 *
 * ```js
 * window.__ModuleLoader__.load({id:`pkg`,factory:require=>{var module={exports:{}};
 * var exports=module.exports; ... exports.apply=apply; return module.exports}});
 * ```
 *
 * 所以策略是：rolldown 输出 CommonJS（保留 `require("react")` 原样），
 * 外层用 banner/footer 拼出上面的壳。CJS 的 `exports.xxx = ...` 正好落到
 * 我们定义的 `exports` 上。
 *
 * 关键：**所有 `@deepseek-ai/*` 与 react 系都 external**。它们由 loader 提供，
 * 打进来会出现第二份 React（hooks 立刻报错），或者与官方实例不共享 context。
 */

import { readFile, writeFile, mkdir } from 'node:fs/promises'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

import { rolldown } from 'rolldown'

const here = dirname(fileURLToPath(import.meta.url))
const pkgRoot = resolve(here, '..')
const PKG_ID = '@studio/ui-shell'
const ENTRY = resolve(pkgRoot, 'src/shell/client-entry.tsx')
const OUT = resolve(pkgRoot, 'lib/client.js')

/** 由 loader 提供、绝不能打进产物的模块。 */
function isExternal(id) {
  if (id === 'react' || id === 'react-dom') return true
  if (id.startsWith('react/')) return true
  if (id.startsWith('react-dom/')) return true
  if (id.startsWith('@deepseek-ai/')) return true
  return false
}

const bundle = await rolldown({
  input: ENTRY,
  external: isExternal,
  platform: 'browser',
  // .ts/.tsx 由 rolldown 内置的 oxc 转换（含 JSX → react/jsx-runtime），无需额外插件。
  resolve: { extensions: ['.tsx', '.ts', '.jsx', '.js'] },
  logLevel: 'warn',
})

const { output } = await bundle.generate({
  format: 'cjs',
  exports: 'named',
  // 便于在 DevTools 里对上行号定位源码。
  sourcemap: true,
})

const chunk = output.find((item) => item.type === 'chunk')
if (!chunk) throw new Error('rolldown 没有产出 chunk')

const stripped = chunk.code.replace(/^\/\/# sourceMappingURL=.*$/gm, '')

const wrapped = [
  `/* generated by scripts/build.mjs — 不要手改 */`,
  `window.__ModuleLoader__.load({`,
  `  id: ${JSON.stringify(PKG_ID)},`,
  `  factory: function (require) {`,
  `    var module = { exports: {} };`,
  `    var exports = module.exports;`,
  stripped,
  `    return module.exports;`,
  `  },`,
  `});`,
  `//# sourceMappingURL=client.js.map`,
  ``,
].join('\n')

await mkdir(dirname(OUT), { recursive: true })
await writeFile(OUT, wrapped, 'utf8')

if (chunk.map) {
  await writeFile(`${OUT}.map`, JSON.stringify(chunk.map), 'utf8')
}

const bytes = (await readFile(OUT)).byteLength
console.log(`✓ lib/client.js  ${(bytes / 1024).toFixed(1)} KB`)
console.log(`  external: react / react-dom / @deepseek-ai/*`)
